&VoucherRequiredFields01;
&VoucherRequiredFields02;
set nocount on select @@fields into #t from d54 a @@join where @@key order by line
select id_px, line_px, sum(a.so_luong*a.he_so) as sl_hd into #slhoadon from d55 a with(index(id_px)) where exists(select 1 from #t b where a.id_px = b.id and a.line_px = b.line) group by id_px, line_px update #t set sl_hd = b.sl_hd from #t a join #slhoadon b on a.id = b.id_px and a.line = b.line_px
update #t set so_ct_hd = b.so_ct from #t a join m54 b on a.id_hd = b.id update #t set so_ct_dh = b.so_ct from #t a join m52 b on a.id_dh = b.id update #t set so_ct_lx = b.so_ct from #t a join m53 b on a.id_lx = b.id
